  const KEY='nexora-connect-workflow-v1',BASE='nexora-community-templates-v1';
  const clone=value=>JSON.parse(JSON.stringify(value));
  const core=window.NEXORA_CONNECT_CORE;if(!core)return;
  const me=core.currentMember,role=core.currentRole,account=core.currentAccount,esc=core.escape;
  const $=selector=>document.querySelector(selector);
  const t=(path,values={})=>{let value=COPY[document.documentElement.lang==='vi'?'vi':'en'];for(const part of path.split('.'))value=value?.[part];return Object.entries(values).reduce((text,[key,item])=>text.replaceAll('{'+key+'}',String(item)),typeof value==='string'?value:path);};
  const date=value=>{const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'':parsed.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});};
  const unique=values=>[...new Set(values.filter(Boolean).map(String))];
  const empty=()=>({version:1,rooms:[],invitations:[],messages:{},meta:{},profiles:{},reports:[]});
  function read(){let value;try{value=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}const data={...empty(),...(value&&typeof value==='object'&&!Array.isArray(value)?value:{})};for(const key of ['rooms','invitations','reports'])if(!Array.isArray(data[key]))data[key]=[];for(const key of ['messages','meta','profiles'])if(!data[key]||typeof data[key]!=='object'||Array.isArray(data[key]))data[key]={};return data;}
  function write(operation,error='members.actionError') {try{const next=read(),result=operation(next);if(result===false)return false;localStorage.setItem(KEY,JSON.stringify(next));return result===undefined?true:result;}catch{core.toast(t(error));return false;}}
  function base(){let value;try{value=JSON.parse(localStorage.getItem(BASE)||'null');}catch{}return value&&typeof value==='object'&&!Array.isArray(value)?value:{groups:clone(window.NEXORA_COMMUNITY_DEMO?.extra?.groups||[]),feed:clone(window.NEXORA_COMMUNITY_DEMO?.extra?.feed||[]),joinedGroups:{}};}
  function saveBase(field,value){try{localStorage.setItem(BASE,JSON.stringify({...base(),[field]:value}));return true;}catch{return false;}}
