  function resolveThread(id){const room=roomForThread(id);if(!room||!roomMember(room))return null;const canonical=room.scope==='PublicCommunity'?publicThread(room.groupId):room.id;let seeds=clone(window.NEXORA_COMMUNITY_DEMO?.connect?.groupMessages?.[room.groupId]||window.NEXORA_COMMUNITY_DEMO?.connect?.rooms?.find(row=>row.id===room.id)?.messages||[]);if(room.groupId==='group-houston')seeds=[{text:'Tiệm mình đang đổi nội thất, có 12 ghế chờ trắng. Anh chị cần mình gửi kích thước nhé.',author:'Mai Nguyễn'},{text:'Mình cần 6 ghế cho khu chờ. Bạn gửi giúp giá theo chiếc và khu vực nhận nhé.',author:'Kim Tuyen'}];else if(room.groupId==='g2')seeds=[{text:'Mình đang tập vẽ hoa nét mảnh trên tip. Có ai ở Houston muốn cùng thực hành buổi tới không?',author:'Mai Nguyễn'},{text:'Cho mình tham gia với. Mình mang cọ liner và tip mẫu, cần chuẩn bị thêm màu gì không?',author:'Kim Tuyen'}];const clear=core.getState().clearedChats?.[id];const messages=[...(clear?[]:seeds.map((message,index)=>({...message,id:canonical+'-seed-'+index,createdAt:new Date(new Date().setHours(9,index,0,0)).toISOString()}))),...(read().messages[canonical]||[])].map(message=>({...message,mine:message.author===me}));return {name:room.name,context:room.scope==='PublicCommunity'?t('members.publicCommunity'):t('members.count',{count:memberNames(room).length}),messages,allowCalls:['PrivateGroup','ShopGroup'].includes(room.scope)};}
  function prepareMessage(thread,value){const room=roomForThread(thread);if(thread.startsWith('group-')&&(!room||!roomMember(room))){core.toast(t('members.actionError'));return false;}if(!room){const state=core.getState(),name=core.members.find(person=>person.detail===thread)?.name||state.sourceChats[thread]?.recipient||(thread==='chat-mai'?'Mai Nguyễn':'');if(name&&(core.isBlocked(name)||!canContact(name))||thread==='chat-mai'&&state.request!=='accepted'){core.toast(t('requests.cardHint'));return false;}}return {...value,...(replyTargets.get(thread)?{replyTo:replyTargets.get(thread)}:{})};}
